-- Additive preparation. Do not apply the separate cutover until the backend is ready.
grant usage on schema public to service_role;
alter table public.staff add column if not exists pin_hash text;
alter table public.staff add column if not exists pin_lookup text;
alter table public.staff add column if not exists auth_version integer not null default 0;
alter table public.staff alter column pin drop not null;
create unique index if not exists staff_pin_lookup_unique on public.staff(pin_lookup) where pin_lookup is not null;
alter table public.products add column if not exists "prepStation" text check ("prepStation" in ('kitchen','none'));

create table if not exists public.app_sessions (
  token_hash text primary key, staff_id bigint not null references public.staff(id) on delete cascade,
  auth_version integer not null,expires_at timestamptz not null,created_at timestamptz not null default now()
);
create table if not exists public.app_login_limits (key text primary key, attempts integer not null, window_at timestamptz not null);
create table if not exists public.app_pin_approvals (token_hash text primary key,session_hash text not null,staff_id bigint not null,expires_at timestamptz not null);
create table if not exists public.app_orders (
  id uuid primary key, label text not null, order_type text not null, items jsonb not null default '[]',
  sent_items jsonb not null default '[]',revision integer not null default 0,
  order_discount numeric not null default 0,order_discount_amount numeric not null default 0,
  running_bill_id bigint,transaction_id bigint references public.transactions(id) on delete set null,
  status text not null default 'open' check(status in ('open','paid','cancelled')),
  staff_id bigint not null,staff_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.kitchen_tickets (
  id uuid primary key default gen_random_uuid(), order_id uuid not null references public.app_orders(id),
  dispatch_key uuid not null unique,items jsonb not null,revision integer not null default 0,
  status text not null default 'new' check(status in ('new','preparing','completed','cancelled')),
  change_notice text,cancel_requested boolean not null default false,
  created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz
);
create index if not exists kitchen_ticket_active on public.kitchen_tickets(status,created_at);
create index if not exists kitchen_ticket_updated on public.kitchen_tickets(updated_at,id);
create table if not exists public.app_order_events (
  id bigint generated by default as identity primary key,order_id uuid, ticket_id uuid,
  actor_id bigint,action text not null,data jsonb not null default '{}',created_at timestamptz not null default now()
);
create table if not exists public.app_dispatch_requests (key uuid primary key,order_id uuid not null,actor_id bigint not null,payload_hash text not null,result jsonb not null);
create table if not exists public.payment_proofs (
  id uuid primary key,checkout_key text not null,method text not null check(method in ('Card','Bank Transfer')),
  amount_cents bigint not null check(amount_cents>0),staff_id bigint not null,
  object_path text not null unique,sha256 text,bytes integer,
  status text not null default 'pending' check(status in ('pending','uploaded','attached','expired','deleted')),
  transaction_id bigint references public.transactions(id) on delete set null,receipt_no text,
  captured_at timestamptz not null default now(),attached_at timestamptz,expires_at timestamptz not null default now()+interval '24 hours'
);
create index if not exists payment_proof_checkout on public.payment_proofs(checkout_key);
create index if not exists payment_proof_expiry on public.payment_proofs(expires_at) where status not in ('expired','deleted');
create table if not exists public.app_checkouts (
  checkout_key text primary key,payload_hash text not null,staff_id bigint not null,
  transaction_id bigint references public.transactions(id) on delete set null,created_at timestamptz not null default now()
);
create table if not exists public.app_stock_effects(id bigint generated by default as identity primary key,transaction_id bigint references public.transactions(id) on delete set null,kind text not null,target_id bigint not null,delta numeric not null,name text,unit text);
do $$ declare t text; begin
  foreach t in array array['app_sessions','app_login_limits','app_pin_approvals','app_orders','kitchen_tickets','app_order_events','app_dispatch_requests','payment_proofs','app_checkouts','app_stock_effects'] loop
    execute format('alter table public.%I enable row level security',t);
    execute format('revoke all on public.%I from public,anon,authenticated',t);
    execute format('grant all on public.%I to service_role',t);
  end loop;
end $$;
grant usage,select on sequence public.app_order_events_id_seq to service_role;
grant usage,select on sequence public.app_stock_effects_id_seq to service_role;

create or replace function public.app_login_limit_v1(p_key text,p_limit integer) returns boolean
language plpgsql security invoker set search_path=public,pg_temp as $$
declare n integer; begin
  insert into app_login_limits as l values(p_key,1,now()) on conflict(key) do update set
    attempts=case when l.window_at<now()-interval '15 minutes' then 1 else l.attempts+1 end,
    window_at=case when l.window_at<now()-interval '15 minutes' then now() else l.window_at end returning attempts into n;
  return n<=p_limit;
end $$;

create or replace function public.app_dispatch_v1(p_actor bigint,p_order uuid,p_revision integer,p_payload jsonb,p_key uuid) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare o app_orders; line jsonb; old jsonb; foods jsonb:='[]'; additions jsonb:='[]'; tid uuid; amount numeric; notice text; actor_name text; retry app_dispatch_requests; ticket kitchen_tickets; desired numeric; allocated numeric; new_quantity numeric;
begin
  if not exists(select 1 from staff where id=p_actor and role in ('owner','manager','cashier')) then raise exception 'Counter account required'; end if;
  select name into actor_name from staff where id=p_actor;
  perform pg_advisory_xact_lock(hashtext(p_order::text));
  select * into retry from app_dispatch_requests where key=p_key;
  if retry.key is not null then
    if retry.order_id<>p_order or retry.actor_id<>p_actor or retry.payload_hash<>md5(p_payload::text) then raise exception 'Dispatch key already used' using errcode='23505'; end if;
    return retry.result;
  end if;
  select * into o from app_orders where id=p_order for update;
  if exists(select 1 from kitchen_tickets where dispatch_key=p_key and order_id=p_order) then
    return (select to_jsonb(app_orders) from app_orders where id=p_order);
  end if;
  if o.id is not null and o.revision<>p_revision then raise exception 'Order changed on another device' using errcode='40001'; end if;
  if o.status in ('cancelled','paid') then raise exception 'Order has already been closed'; end if;
  if jsonb_typeof(p_payload->'items')<>'array' or jsonb_array_length(p_payload->'items')=0 then raise exception 'Add order items first'; end if;
  if nullif(trim(p_payload->>'label'),'') is null then raise exception 'Table or order label is required'; end if;
  if exists(select 1 from jsonb_array_elements(p_payload->'items') i group by i->>'lineId' having count(*)>1) then raise exception 'Duplicate order line'; end if;
  for line in select value from jsonb_array_elements(p_payload->'items') loop
    if nullif(line->>'lineId','') is null or (line->>'quantity')::numeric<=0 then raise exception 'Invalid order line'; end if;
    if not exists(select 1 from products p where p.id::text=line->>'productId') then raise exception 'Product not found'; end if;
    if exists(select 1 from products p where p.id::text=line->>'productId' and coalesce(p."prepStation",case when lower(p.category)='food' then 'kitchen' else 'none' end)='kitchen'
      and coalesce(p."reportingType",case when lower(p.name) like 'milk%waste%' then 'waste' when lower(p.category) in ('takeout box','packaging') then 'packaging' else 'sale' end)='sale') then
      line:=line||jsonb_build_object('name',(select name from products where id::text=line->>'productId'));
      foods:=foods||jsonb_build_array(line);
    end if;
  end loop;
  if o.id is null then
    insert into app_orders(id,label,order_type,items,staff_id,staff_name,running_bill_id) values
      (p_order,p_payload->>'label',coalesce(p_payload->>'orderType','Dine In'),p_payload->'items',p_actor,actor_name,(p_payload->>'billId')::bigint) returning * into o;
  end if;
  for line in select value from jsonb_array_elements(foods) loop
    select value into old from jsonb_array_elements(o.sent_items) where value->>'lineId'=line->>'lineId';
    amount:=(line->>'quantity')::numeric-coalesce((old->>'quantity')::numeric,0);
    if old is not null and (coalesce(old->>'note','')<>coalesce(line->>'note','') or amount<0) then
      notice:=format('CHANGE: %s now %s ×, notes: %s',line->>'name',line->>'quantity',coalesce(line->>'note','none'));
      update kitchen_tickets set change_notice=concat_ws(E'\n',change_notice,notice),revision=revision+1,updated_at=now() where order_id=p_order and status<>'cancelled';
      desired:=(line->>'quantity')::numeric; allocated:=0;
      for ticket in select * from kitchen_tickets where order_id=p_order and status<>'cancelled' order by created_at,id for update loop
        select coalesce((i->>'quantity')::numeric,0) into new_quantity from jsonb_array_elements(ticket.items) i where i->>'lineId'=line->>'lineId';
        if new_quantity is null then continue; end if;
        new_quantity:=least(new_quantity,greatest(0,desired-allocated)); allocated:=allocated+new_quantity;
        update kitchen_tickets set items=(select jsonb_agg(case when i->>'lineId'=line->>'lineId' then i||jsonb_build_object('quantity',new_quantity,'note',coalesce(line->>'note',''),'removed',new_quantity=0) else i end) from jsonb_array_elements(ticket.items) i) where id=ticket.id;
      end loop;
    end if;
    if amount>0 then additions:=additions||jsonb_build_array(jsonb_build_object('lineId',line->>'lineId','name',line->>'name','quantity',amount,'note',coalesce(line->>'note',''),'done',false)); end if;
  end loop;
  for old in select value from jsonb_array_elements(o.sent_items) loop
    if not exists(select 1 from jsonb_array_elements(foods) l where l->>'lineId'=old->>'lineId') then
      update kitchen_tickets set change_notice=concat_ws(E'\n',change_notice,'REMOVE: '||(old->>'name')),revision=revision+1,updated_at=now() where order_id=p_order and status<>'cancelled';
      update kitchen_tickets set items=(select jsonb_agg(case when i->>'lineId'=old->>'lineId' then i||jsonb_build_object('quantity',0,'removed',true) else i end) from jsonb_array_elements(items) i) where order_id=p_order and status<>'cancelled';
    end if;
  end loop;
  if jsonb_array_length(additions)>0 then
    insert into kitchen_tickets(order_id,dispatch_key,items) values(p_order,p_key,additions) returning id into tid;
  end if;
  update app_orders set items=p_payload->'items',sent_items=foods,label=p_payload->>'label',order_type=coalesce(p_payload->>'orderType',order_type),order_discount=coalesce((p_payload->>'orderDiscount')::numeric,0),order_discount_amount=coalesce((p_payload->>'orderDiscountAmount')::numeric,0),revision=revision+1,updated_at=now() where id=p_order returning * into o;
  insert into app_order_events(order_id,ticket_id,actor_id,action,data) values(p_order,tid,p_actor,'DISPATCH',jsonb_build_object('dispatchKey',p_key,'newLines',jsonb_array_length(additions)));
  if o.running_bill_id is not null then update running_bills set items=o.items,"updatedAt"=(extract(epoch from now())*1000)::bigint where id=o.running_bill_id; end if;
  insert into app_dispatch_requests values(p_key,p_order,p_actor,md5(p_payload::text),to_jsonb(o));
  return to_jsonb(o);
end $$;

create or replace function public.app_ticket_action_v1(p_actor bigint,p_ticket uuid,p_revision integer,p_action text,p_line text default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare t kitchen_tickets; role_name text; begin
  select role into role_name from staff where id=p_actor;
  if role_name not in ('owner','manager','cashier','kitchen') or role_name is null then raise exception 'Kitchen access required'; end if;
  select * into t from kitchen_tickets where id=p_ticket for update;
  if t.id is null then raise exception 'Ticket not found'; end if;
  if t.revision<>p_revision then raise exception 'Ticket changed; refresh and retry' using errcode='40001'; end if;
  if t.status='cancelled' then raise exception 'Ticket is cancelled'; end if;
  if p_action='toggle' then
    if t.status='completed' then raise exception 'Reopen the completed ticket first'; end if;
    if t.status='cancelled' or t.cancel_requested or t.change_notice is not null then raise exception 'Acknowledge the change before preparing'; end if;
    if not exists(select 1 from jsonb_array_elements(t.items) i where i->>'lineId'=p_line) then raise exception 'Item not found'; end if;
    select jsonb_agg(case when i->>'lineId'=p_line then jsonb_set(i,'{done}',to_jsonb(not (i->>'done')::boolean)) else i end) into t.items from jsonb_array_elements(t.items) i;
    t.status:='preparing'; t.completed_at:=null;
  elsif p_action='start' then if t.status<>'new' or t.change_notice is not null then raise exception 'Acknowledge changes first'; end if; t.status:='preparing';
  elsif p_action='complete' then
    if t.cancel_requested or t.change_notice is not null or exists(select 1 from jsonb_array_elements(t.items) i where coalesce((i->>'quantity')::numeric,0)>0 and not (i->>'done')::boolean) then raise exception 'Check every item and acknowledge changes first'; end if;
    t.status:='completed'; t.completed_at:=now();
  elsif p_action='reopen' then
    if t.status<>'completed' then raise exception 'Only completed tickets can reopen'; end if;
    t.status:='preparing'; t.completed_at:=null;
  elsif p_action='acknowledge' then
    if t.cancel_requested or not exists(select 1 from jsonb_array_elements(t.items) i where (i->>'quantity')::numeric>0) then t.status:='cancelled'; end if; t.change_notice:=null;
  else raise exception 'Unknown ticket action'; end if;
  update kitchen_tickets set items=t.items,status=t.status,change_notice=t.change_notice,completed_at=t.completed_at,revision=revision+1,updated_at=now() where id=t.id returning * into t;
  insert into app_order_events(order_id,ticket_id,actor_id,action) values(t.order_id,t.id,p_actor,upper(p_action));
  return to_jsonb(t);
end $$;

create or replace function public.app_cancel_order_v1(p_actor bigint,p_order uuid,p_reason text) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
  if not exists(select 1 from staff where id=p_actor and role in ('owner','manager','cashier')) then raise exception 'Counter access required'; end if;
  if length(trim(p_reason))<3 then raise exception 'Cancellation reason required'; end if;
  perform 1 from app_orders where id=p_order and status='open' for update;
  if not found then raise exception 'Only unpaid open orders can be cancelled'; end if;
  update app_orders set status='cancelled',revision=revision+1,updated_at=now() where id=p_order;
  update kitchen_tickets set cancel_requested=true,change_notice='CANCEL: '||p_reason,revision=revision+1,updated_at=now() where order_id=p_order and status<>'cancelled';
  insert into app_order_events(order_id,actor_id,action,data) values(p_order,p_actor,'CANCEL_REQUEST',jsonb_build_object('reason',p_reason));
end $$;

-- Checkout, stock and loyalty changes commit together. Existing receipts are never backfilled.
create or replace function public.app_checkout_v1(p_actor bigint,p_payload jsonb,p_hash text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare prior app_checkouts; actor staff; tx transactions; c customers; item jsonb; part jsonb; proof payment_proofs; product products; link record; ing ingredients; inv inventory;
  total numeric; subtotal numeric:=0; v_unit numeric; paid numeric:=0; cash numeric:=0; change_due numeric; discount numeric; points_discount numeric:=0; earned integer:=0; redeemed integer:=0; before_points numeric;
  clean_lines jsonb:='[]'; snapshots jsonb:='[]'; order_row jsonb; order_id uuid; v_checkout_key text:=p_payload->>'checkoutKey'; now_ms bigint:=(extract(epoch from clock_timestamp())*1000)::bigint;
begin
  select * into actor from staff where id=p_actor and role in ('owner','manager','cashier');
  if actor.id is null then raise exception 'Counter account required'; end if;
  if length(coalesce(v_checkout_key,''))<10 then raise exception 'Checkout key required'; end if;
  perform pg_advisory_xact_lock(hashtext(v_checkout_key));
  select * into prior from app_checkouts where app_checkouts.checkout_key=v_checkout_key;
  if prior.checkout_key is not null then
    if prior.staff_id<>p_actor or prior.payload_hash<>p_hash then raise exception 'Checkout key has different payment details' using errcode='23505'; end if;
    select * into tx from transactions where id=prior.transaction_id;
    if tx.id is null or tx.status='void' then raise exception 'This checkout was already reversed'; end if;
    return to_jsonb(tx);
  end if;
  if jsonb_typeof(p_payload->'items')<>'array' or jsonb_array_length(p_payload->'items')=0 then raise exception 'Order is empty'; end if;
  if exists(select 1 from jsonb_array_elements(p_payload->'paymentLines') p group by p->>'method' having count(*)>1) then raise exception 'Duplicate payment method'; end if;
  if p_payload->>'billId' is not null then
    perform 1 from running_bills where id=(p_payload->>'billId')::bigint and status='open' and "updatedAt"=(p_payload->>'expectedBillUpdatedAt')::bigint for update;
    if not found then raise exception 'Running bill already closed' using errcode='40001'; end if;
  end if;
  for item in select value from jsonb_array_elements(p_payload->'items') loop
    select * into product from products where id::text=item->>'productId';
    if product.id is null or (item->>'quantity')::numeric<=0 then raise exception 'Invalid product or quantity'; end if;
    if (item->>'price')::numeric<0 or (item->>'discount')::numeric not between 0 and 100 or coalesce((item->>'customPrice')::numeric,0)<0 then raise exception 'Invalid price adjustment'; end if;
    -- Keep the order's saved selling price; snapshot the current verified cost on this new sale.
    item:=item||jsonb_build_object('cost',product.cost,'reportingType',coalesce(product."reportingType",case when lower(product.name) like 'milk%waste%' then null when lower(product.category) in ('food','drinks') then 'sale' when lower(product.category) in ('takeout box','packaging') then 'packaging' else null end),'costZeroConfirmed',product."costZeroConfirmed");
    v_unit:=case when coalesce((item->>'customPrice')::numeric,0)>0 then (item->>'customPrice')::numeric else greatest(0,(item->>'price')::numeric*(1-coalesce((item->>'discount')::numeric,0)/100)*(1+coalesce((item->>'markup')::numeric,0)/100)-coalesce((item->>'discountAmount')::numeric,0)+coalesce((item->>'markupAmount')::numeric,0)) end;
    subtotal:=subtotal+v_unit*(item->>'quantity')::numeric; snapshots:=snapshots||jsonb_build_array(item);
  end loop;
  discount:=coalesce((p_payload->>'orderDiscount')::numeric,0);
  if discount not between 0 and 100 or coalesce((p_payload->>'orderDiscountAmount')::numeric,0)<0 then raise exception 'Invalid order discount'; end if;
  total:=round(greatest(0,subtotal*(1-discount/100)-coalesce((p_payload->>'orderDiscountAmount')::numeric,0)),2);
  if p_payload->>'customerId' is not null then
    select * into c from customers where id=(p_payload->>'customerId')::bigint for update;
    if c.id is null or c.status<>'active' or c."expiresAt"<=now_ms then raise exception 'Customer membership is not active'; end if;
    points_discount:=coalesce((p_payload->>'loyaltyDiscount')::numeric,0);
    if points_discount<0 or points_discount>least(floor(c."pointsBalance"/10),floor(total)) then raise exception 'Invalid loyalty redemption'; end if;
    redeemed:=ceil(points_discount*10); total:=greatest(0,total-points_discount); earned:=floor(total/100);
  elsif coalesce((p_payload->>'loyaltyDiscount')::numeric,0)<>0 then raise exception 'Customer required for loyalty'; end if;
  for part in select value from jsonb_array_elements(p_payload->'paymentLines') loop
    if part->>'method' not in ('Cash','GCash','Card','Bank Transfer','Grab','Foodpanda') or (part->>'amount')::numeric<0 then raise exception 'Invalid payment method or amount'; end if;
    paid:=paid+round((part->>'amount')::numeric,2); if part->>'method'='Cash' then cash:=cash+round((part->>'amount')::numeric,2); end if;
  end loop;
  if paid<total or paid-cash>total then raise exception 'Payment amounts do not match the amount due'; end if;
  change_due:=paid-total;
  for part in select value from jsonb_array_elements(p_payload->'paymentLines') loop
    v_unit:=round((part->>'amount')::numeric,2); if part->>'method'='Cash' then v_unit:=greatest(0,v_unit-change_due); change_due:=greatest(0,change_due-(part->>'amount')::numeric); end if;
    if v_unit<=0 then continue; end if;
    if part->>'method' in ('Card','Bank Transfer') then
      select * into proof from payment_proofs where id::text=(p_payload->'proofs'->>(part->>'method')) and payment_proofs.checkout_key=v_checkout_key and staff_id=p_actor for update;
      if proof.id is null or proof.status<>'uploaded' or proof.expires_at<=now() or proof.method<>part->>'method' or proof.amount_cents<>round(v_unit*100)::bigint then raise exception 'A fresh uploaded payment photo is required for %',part->>'method'; end if;
    end if;
    clean_lines:=clean_lines||jsonb_build_array(jsonb_build_object('method',part->>'method','amount',v_unit));
  end loop;
  order_id:=(p_payload->>'orderId')::uuid;
  if order_id is null and exists(select 1 from jsonb_array_elements(snapshots) i join products p on p.id::text=i->>'productId' where coalesce(p."prepStation",case when lower(p.category)='food' then 'kitchen' else 'none' end)='kitchen' and coalesce(i->>'reportingType','sale')='sale') then raise exception 'Food checkout requires a kitchen order label'; end if;
  if order_id is not null then
    order_row:=app_dispatch_v1(p_actor,order_id,coalesce((p_payload->>'orderRevision')::integer,0),jsonb_build_object('label',p_payload->>'orderLabel','orderType',p_payload->>'orderType','items',snapshots,'billId',p_payload->'billId','orderDiscount',discount,'orderDiscountAmount',p_payload->'orderDiscountAmount'),(p_payload->>'dispatchKey')::uuid);
    if exists(select 1 from app_orders where id=order_id and status='paid') then raise exception 'Order has already been paid'; end if;
  end if;
  insert into transactions("receiptNo","checkoutKey",datetime,"orderType",items,"paymentMethod","paymentLines","orderDiscount","orderDiscountAmount",subtotal,"customerId","customerName","memberCode","loyaltyEarned","loyaltyRedeemed","loyaltyDiscount","birthdayRewardRedeemed",total,"cashReceived","staffId","staffName",status)
    values(p_payload->>'receiptNo',v_checkout_key,now_ms,p_payload->>'orderType',snapshots,coalesce((select string_agg(p->>'method',' + ') from jsonb_array_elements(clean_lines) p),'Loyalty'),clean_lines,discount,coalesce((p_payload->>'orderDiscountAmount')::numeric,0),subtotal,c.id,c.name,c."memberCode",earned,redeemed,points_discount,false,total,cash,actor.id,actor.name,'completed') returning * into tx;
  if coalesce((p_payload->>'birthdayRewardRedeemed')::boolean,false) then
    if c.id is null or c.birthday is null or extract(month from c.birthday::date)<>extract(month from now() at time zone 'Asia/Manila') or c."birthdayRewardYear"=extract(year from now() at time zone 'Asia/Manila')::integer then raise exception 'Birthday reward is not eligible'; end if;
    update customers set "birthdayRewardYear"=extract(year from now() at time zone 'Asia/Manila')::integer where id=c.id;
    update transactions set "birthdayRewardRedeemed"=true where id=tx.id returning * into tx;
    insert into loyalty_transactions("customerId","customerName","memberCode","transactionId","receiptNo",type,points,amount,"beforePoints","afterPoints",details,"staffId","staffName",datetime) values(c.id,c.name,c."memberCode",tx.id,tx."receiptNo",'BIRTHDAY_REWARD',0,0,c."pointsBalance",c."pointsBalance",'Birthday reward',actor.id,actor.name,now_ms);
  end if;
  if c.id is not null then
    before_points:=c."pointsBalance"; update customers set "pointsBalance"=before_points-redeemed+earned,"updatedAt"=now_ms where id=c.id;
    if redeemed>0 then insert into loyalty_transactions("customerId","customerName","memberCode","transactionId","receiptNo",type,points,amount,"beforePoints","afterPoints",details,"staffId","staffName",datetime) values(c.id,c.name,c."memberCode",tx.id,tx."receiptNo",'REDEEM',-redeemed,points_discount,before_points,before_points-redeemed,'Checkout redemption',actor.id,actor.name,now_ms); end if;
    if earned>0 then insert into loyalty_transactions("customerId","customerName","memberCode","transactionId","receiptNo",type,points,amount,"beforePoints","afterPoints",details,"staffId","staffName",datetime) values(c.id,c.name,c."memberCode",tx.id,tx."receiptNo",'EARN',earned,total,before_points-redeemed,before_points-redeemed+earned,'Checkout earned points',actor.id,actor.name,now_ms); end if;
  end if;
  for item in select value from jsonb_array_elements(snapshots) loop
    for link in select * from product_ingredients where "productId"=(item->>'productId')::bigint loop
      select * into ing from ingredients where id=link."ingredientId" for update;
      v_unit:=greatest(0,ing."inStock"-link.quantity*(item->>'quantity')::numeric);
      update ingredients set "inStock"=v_unit where id=ing.id;
      insert into app_stock_effects(transaction_id,kind,target_id,delta,name,unit) values(tx.id,'ingredient',ing.id,v_unit-ing."inStock",ing.name,ing.unit);
      insert into ingredient_movements("ingredientId","ingredientName","transactionId","receiptNo",type,quantity,unit,"beforeStock","afterStock","staffId","staffName","productName",datetime) values(ing.id,ing.name,tx.id,tx."receiptNo",'DEDUCT',link.quantity*(item->>'quantity')::numeric,ing.unit,ing."inStock",v_unit,actor.id,actor.name,item->>'name',now_ms);
    end loop;
    for link in select * from product_inventory where "productId"=(item->>'productId')::bigint loop
      select * into inv from inventory where id=link."inventoryId" for update;
      update inventory set "inStock"=greatest(0,"inStock"-link.quantity*(item->>'quantity')::numeric) where id=link."inventoryId";
      insert into app_stock_effects(transaction_id,kind,target_id,delta,name) values(tx.id,'inventory',inv.id,greatest(0,inv."inStock"-link.quantity*(item->>'quantity')::numeric)-inv."inStock",inv.name);
    end loop;
  end loop;
  insert into daily_sales_summary("businessDate","transactionCount",revenue,cost,profit,"itemCount","updatedAt")
    select (to_timestamp(now_ms/1000.0) at time zone 'Asia/Manila')::date,1,total,sum(coalesce((i->>'cost')::numeric,0)*(i->>'quantity')::numeric),total-sum(coalesce((i->>'cost')::numeric,0)*(i->>'quantity')::numeric),sum((i->>'quantity')::numeric),now_ms from jsonb_array_elements(snapshots) i
    on conflict("businessDate") do update set "transactionCount"=daily_sales_summary."transactionCount"+1,revenue=daily_sales_summary.revenue+excluded.revenue,cost=daily_sales_summary.cost+excluded.cost,profit=daily_sales_summary.profit+excluded.profit,"itemCount"=daily_sales_summary."itemCount"+excluded."itemCount","updatedAt"=excluded."updatedAt";
  update payment_proofs set status='attached',transaction_id=tx.id,receipt_no=tx."receiptNo",attached_at=now(),expires_at=now()+interval '90 days'
    where payment_proofs.checkout_key=v_checkout_key and staff_id=p_actor and method in(select p->>'method' from jsonb_array_elements(clean_lines) p)
      and id::text in(select value from jsonb_each_text(p_payload->'proofs'));
  if order_id is not null then update app_orders set status='paid',transaction_id=tx.id,revision=revision+1,updated_at=now() where id=order_id; end if;
  if p_payload->>'billId' is not null then update running_bills set status='closed',"transactionId"=tx.id,"closedAt"=now_ms,"updatedAt"=now_ms where id=(p_payload->>'billId')::bigint and status='open'; if not found then raise exception 'Running bill was already closed'; end if; end if;
  insert into app_checkouts(checkout_key,payload_hash,staff_id,transaction_id) values(v_checkout_key,p_hash,p_actor,tx.id);
  return to_jsonb(tx);
end $$;

create or replace function public.app_reverse_transaction_v1(p_actor bigint,p_id bigint,p_reason text,p_delete boolean default false) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare tx transactions; actor staff; c customers; item jsonb; link record; ing ingredients; qty numeric; delta numeric; now_ms bigint:=(extract(epoch from now())*1000)::bigint;
begin
  select * into actor from staff where id=p_actor and role in ('owner','manager');
  if actor.id is null or (p_delete and actor.role<>'owner') then raise exception 'Manager or owner authorization required'; end if;
  if length(trim(p_reason))<3 then raise exception 'Reason required'; end if;
  select * into tx from transactions where id=p_id for update; if tx.id is null then return; end if;
  if tx.status<>'void' then
    if exists(select 1 from app_checkouts where transaction_id=p_id) then
      for link in select * from app_stock_effects where transaction_id=p_id loop
        if link.kind='ingredient' then
          select * into ing from ingredients where id=link.target_id for update;
          update ingredients set "inStock"="inStock"-link.delta where id=link.target_id;
          insert into ingredient_movements("ingredientId","ingredientName","transactionId","receiptNo",type,quantity,unit,"beforeStock","afterStock","staffId","staffName",datetime) values(ing.id,link.name,tx.id,tx."receiptNo",'RESTOCK',-link.delta,link.unit,ing."inStock",ing."inStock"-link.delta,actor.id,actor.name,now_ms);
        else update inventory set "inStock"="inStock"-link.delta where id=link.target_id; end if;
      end loop;
    else
    for item in select value from jsonb_array_elements(tx.items) loop
      for link in select * from product_ingredients where "productId"=(item->>'productId')::bigint loop
        select * into ing from ingredients where id=link."ingredientId" for update; qty:=link.quantity*(item->>'quantity')::numeric;
        update ingredients set "inStock"="inStock"+qty where id=ing.id;
        insert into ingredient_movements("ingredientId","ingredientName","transactionId","receiptNo",type,quantity,unit,"beforeStock","afterStock","staffId","staffName","productName",datetime) values(ing.id,ing.name,tx.id,tx."receiptNo",'RESTOCK',qty,ing.unit,ing."inStock",ing."inStock"+qty,actor.id,actor.name,item->>'name',now_ms);
      end loop;
      for link in select * from product_inventory where "productId"=(item->>'productId')::bigint loop update inventory set "inStock"="inStock"+link.quantity*(item->>'quantity')::numeric where id=link."inventoryId"; end loop;
    end loop;
    end if;
    update daily_sales_summary set "transactionCount"=greatest(0,"transactionCount"-1),revenue=greatest(0,revenue-tx.total),cost=greatest(0,cost-coalesce((select sum(coalesce((i->>'cost')::numeric,0)*(i->>'quantity')::numeric) from jsonb_array_elements(tx.items) i),0)),profit=profit-tx.total+coalesce((select sum(coalesce((i->>'cost')::numeric,0)*(i->>'quantity')::numeric) from jsonb_array_elements(tx.items) i),0),"itemCount"=greatest(0,"itemCount"-coalesce((select sum((i->>'quantity')::numeric) from jsonb_array_elements(tx.items) i),0)),"updatedAt"=now_ms where "businessDate"=(to_timestamp(tx.datetime/1000.0) at time zone 'Asia/Manila')::date;
    if tx."customerId" is not null then
      select * into c from customers where id=tx."customerId" for update;
      delta:=coalesce(tx."loyaltyRedeemed",0)-coalesce(tx."loyaltyEarned",0);
      update customers set "pointsBalance"=greatest(0,"pointsBalance"+delta),"birthdayRewardYear"=case when tx."birthdayRewardRedeemed" and "birthdayRewardYear"=extract(year from to_timestamp(tx.datetime/1000.0) at time zone 'Asia/Manila')::integer then null else "birthdayRewardYear" end,"updatedAt"=now_ms where id=c.id;
      if delta<>0 then insert into loyalty_transactions("customerId","customerName","memberCode","transactionId","receiptNo",type,points,amount,"beforePoints","afterPoints",details,"staffId","staffName",datetime) values(c.id,c.name,c."memberCode",tx.id,tx."receiptNo",'REVERSAL',delta,coalesce(tx."loyaltyDiscount",0),c."pointsBalance",greatest(0,c."pointsBalance"+delta),p_reason,actor.id,actor.name,now_ms); end if;
    end if;
  end if;
  update kitchen_tickets set cancel_requested=true,change_notice='VOID: '||p_reason,revision=revision+1,updated_at=now() where order_id in(select id from app_orders where transaction_id=p_id) and status<>'cancelled';
  update app_orders set status='cancelled',revision=revision+1,updated_at=now() where transaction_id=p_id;
  if p_delete then delete from void_log where "transactionId"=p_id; delete from transactions where id=p_id;
  elsif tx.status<>'void' then update transactions set status='void' where id=p_id;insert into void_log("transactionId","receiptNo",reason,"staffId","staffName",datetime,"originalData") values(tx.id,tx."receiptNo",p_reason,actor.id,actor.name,now_ms,to_jsonb(tx)); end if;
  insert into app_order_events(actor_id,action,data) values(p_actor,case when p_delete then 'DELETE_TRANSACTION' else 'VOID_TRANSACTION' end,jsonb_build_object('receiptNo',tx."receiptNo",'reason',p_reason));
end $$;
revoke all on function public.app_reverse_transaction_v1(bigint,bigint,text,boolean) from public,anon,authenticated;
grant execute on function public.app_reverse_transaction_v1(bigint,bigint,text,boolean) to service_role;

create or replace function public.app_kitchen_feed_v1(p_actor bigint,p_since timestamptz default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb; begin
  if not exists(select 1 from staff where id=p_actor and role in ('owner','manager','cashier','kitchen')) then raise exception 'Kitchen access required'; end if;
  with rows as materialized(select t.id,t.order_id,t.items,t.revision,t.status,t.change_notice,t.cancel_requested,t.created_at,t.updated_at,t.completed_at,
    jsonb_build_object('label',o.label,'order_type',o.order_type,'staff_name',o.staff_name) as app_orders
    from kitchen_tickets t join app_orders o on o.id=t.order_id
    where (p_since is not null and t.updated_at>=p_since) or (p_since is null and (t.status in ('new','preparing') or t.change_notice is not null or t.updated_at>=now()-interval '24 hours')))
  select jsonb_build_object('tickets',coalesce(jsonb_agg(to_jsonb(rows) order by created_at,id),'[]'),'cursor',coalesce(max(updated_at),p_since),'asOf',statement_timestamp()) into result from rows;
  return result;
end $$;
revoke all on function public.app_kitchen_feed_v1(bigint,timestamptz) from public,anon,authenticated;
grant execute on function public.app_kitchen_feed_v1(bigint,timestamptz) to service_role;

create or replace function public.app_save_bill_v1(p_actor bigint,p_id bigint,p_expected bigint,p_data jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare b running_bills; actor_name text; now_ms bigint:=(extract(epoch from clock_timestamp())*1000)::bigint; begin
  select name into actor_name from staff where id=p_actor and role in ('owner','manager','cashier'); if actor_name is null then raise exception 'Counter access required'; end if;
  if p_id is not null then
    select * into b from running_bills where id=p_id for update;
    if b.id is null or b.status<>'open' or b."updatedAt"<>p_expected then raise exception 'Running bill changed on another tablet' using errcode='40001'; end if;
    update running_bills set items=p_data->'items',"tableName"=p_data->>'tableName',"orderType"=p_data->>'orderType',"orderDiscount"=coalesce((p_data->>'orderDiscount')::numeric,0),"orderDiscountAmount"=coalesce((p_data->>'orderDiscountAmount')::numeric,0),total=(p_data->>'total')::numeric,"updatedAt"=now_ms where id=p_id returning * into b;
  else
    insert into running_bills(items,"tableName","orderType","orderDiscount","orderDiscountAmount",total,status,"staffId","staffName","openedAt","updatedAt") values(p_data->'items',p_data->>'tableName',p_data->>'orderType',coalesce((p_data->>'orderDiscount')::numeric,0),coalesce((p_data->>'orderDiscountAmount')::numeric,0),(p_data->>'total')::numeric,'open',p_actor,actor_name,now_ms,now_ms) returning * into b;
  end if;
  return to_jsonb(b);
end $$;
revoke all on function public.app_save_bill_v1(bigint,bigint,bigint,jsonb) from public,anon,authenticated;
grant execute on function public.app_save_bill_v1(bigint,bigint,bigint,jsonb) to service_role;

create or replace function public.app_link_bill_v1(p_actor bigint,p_order uuid,p_bill bigint,p_revision integer) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare o app_orders; begin
  if not exists(select 1 from staff where id=p_actor and role in ('owner','manager','cashier')) then raise exception 'Counter access required'; end if;
  select * into o from app_orders where id=p_order for update;
  if o.revision<>p_revision or o.status<>'open' then raise exception 'Order changed on another tablet' using errcode='40001'; end if;
  if not exists(select 1 from running_bills where id=p_bill and status='open') then raise exception 'Running bill not found'; end if;
  update app_orders set running_bill_id=p_bill,revision=revision+1,updated_at=now() where id=p_order returning * into o; return to_jsonb(o);
end $$;
create unique index if not exists app_order_bill_unique on public.app_orders(running_bill_id) where running_bill_id is not null;
revoke all on function public.app_link_bill_v1(bigint,uuid,bigint,integer) from public,anon,authenticated;
grant execute on function public.app_link_bill_v1(bigint,uuid,bigint,integer) to service_role;

-- Extend existing single-column role checks without rewriting historical staff.
do $$ declare c record; begin
  for c in select conname from pg_constraint where conrelid='public.staff'::regclass and contype='c' and array_length(conkey,1)=1 and conkey[1]=(select attnum from pg_attribute where attrelid='public.staff'::regclass and attname='role') loop execute format('alter table public.staff drop constraint %I',c.conname); end loop;
  if not exists(select 1 from pg_constraint where conrelid='public.staff'::regclass and conname='app_staff_roles') then alter table public.staff add constraint app_staff_roles check(role in ('owner','manager','cashier','staff','kitchen')) not valid; end if;
end $$;

do $$ begin
  if to_regclass('storage.buckets') is not null then
    execute $q$insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('payment-proofs','payment-proofs',false,1048576,array['image/jpeg']) on conflict(id) do update set public=false,file_size_limit=1048576,allowed_mime_types=array['image/jpeg']$q$;
  end if;
  -- Restrictive policy also blocks this bucket under any pre-existing broad
  -- client Storage policies. Server service-role requests bypass RLS.
  if to_regclass('storage.objects') is not null then
    execute 'drop policy if exists payment_proofs_server_only on storage.objects';
    execute $q$create policy payment_proofs_server_only on storage.objects as restrictive for all to anon,authenticated using(bucket_id<>'payment-proofs') with check(bucket_id<>'payment-proofs')$q$;
  end if;
end $$;

do $$ declare f record; begin
  for f in select oid::regprocedure as signature from pg_proc where pronamespace='public'::regnamespace and proname in ('app_login_limit_v1','app_dispatch_v1','app_ticket_action_v1','app_cancel_order_v1','app_checkout_v1') loop
    execute format('revoke all on function %s from public,anon,authenticated',f.signature);
    execute format('grant execute on function %s to service_role',f.signature);
  end loop;
end $$;
